      t.appendChild(el('<div class="tile"><div class="k">'+esc(x[0])+'</div><div class="v num">'+esc(String(x[1] === undefined || x[1] === null ? "—" : x[1]))+'</div>'+(x[2] ? '<div class="s">'+esc(x[2])+'</div>' : '')+'</div>'));
